and blocks. Reading never raises on a missing or malformed canon; the problem is kept in `error`."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .confined import inside


def canon_root(env: dict[str, str] | None = None) -> Path:
    env = os.environ if env is None else env
    return Path(env.get("DS_CANON") or Path.home() / "Developer" / "canon").expanduser()


def _entries(index: dict, key: str) -> list[dict[str, Any]]:
    """Entries of one list that have a string id; anything else in the index is skipped."""
    items = index.get(key, [])
    if isinstance(items, dict):                    # {id: entry} is accepted as well as [entry]
        items = [{"id": k, **v} for k, v in items.items() if isinstance(v, dict)]
    if not isinstance(items, list):
        return []
    return [e for e in items if isinstance(e, dict) and isinstance(e.get("id"), str) and e["id"]]


@dataclass
class Canon:
    root: Path
    standards: list[dict[str, Any]] = field(default_factory=list)
    scaffolds: list[dict[str, Any]] = field(default_factory=list)
    blocks: list[dict[str, Any]] = field(default_factory=list)
    error: str = ""

    @classmethod
    def load(cls, root: Path) -> Canon:
        root = Path(root)
        path = root / "index.json"
        try:
            index = json.loads(path.read_text())
        except FileNotFoundError:
            return cls(root, error=f"no canon at {root} (index.json not found); set DS_CANON")
        except (OSError, ValueError) as e:
            return cls(root, error=f"cannot read {path}: {e}")
        if not isinstance(index, dict):
            return cls(root, error=f"{path} is not a JSON object")
        return cls(root, _entries(index, "standards"), _entries(index, "scaffolds"), _entries(index, "blocks"))

