        return [s for s in self.scaffolds if s.get("status") == "accepted"]

    def accepted_blocks(self) -> list[dict[str, Any]]:
        """Blocks without a status are listed: the index only carries accepted ones today."""
        return [b for b in self.blocks if b.get("status", "accepted") == "accepted"]

