"""What a repo's .ds/manifest.toml records, against the canon. [[gotcha-validation]]

Never raises on bad input: every malformed value becomes a problem line."""
from __future__ import annotations

import datetime as dt
import fnmatch
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

from .canon import Canon, version


@dataclass
class Report:
    adopted: list[str] = field(default_factory=list)
    declined: list[str] = field(default_factory=list)
    newer: list[str] = field(default_factory=list)
    missing: list[str] = field(default_factory=list)
    blocks: list[str] = field(default_factory=list)
    problems: list[str] = field(default_factory=list)


def _applies(applies_to, tags: list[str]) -> bool:
    if applies_to in (None, "", "*"):
        return True
    patterns = [applies_to] if isinstance(applies_to, str) else applies_to
    if not isinstance(patterns, list):
        return False
    return any(isinstance(p, str) and (p == "*" or any(fnmatch.fnmatchcase(t, p) for t in tags)) for p in patterns)


def _text(v) -> bool:
    return isinstance(v, str) and bool(v.strip())


def _is_date(v) -> bool:
    """A TOML date, or an ISO date string; a datetime is not a date here."""
    if isinstance(v, dt.datetime):
        return False
    if isinstance(v, dt.date):
        return True
    if isinstance(v, str):
        try:
            dt.date.fromisoformat(v)
            return True
        except ValueError:
            return False
    return False


def _int(v) -> int | None:
    return v if isinstance(v, int) and not isinstance(v, bool) else None


def manifest_report(repo: Path, canon: Canon) -> Report:
    r = Report()
    path = Path(repo) / ".ds" / "manifest.toml"
    try:
        data = tomllib.loads(path.read_text())
    except FileNotFoundError:
        r.problems.append(f"no {path.relative_to(repo)} here: this is not a ds repository")
        return r
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as e:
        r.problems.append(f"cannot read {path}: {e}")
        return r

    repo_t = data.get("repo")
    if not isinstance(repo_t, dict):
        r.problems.append("[repo] is missing or not a table")
        repo_t = {}
    tags = repo_t.get("tags", [])
    if not (isinstance(tags, list) and all(isinstance(t, str) for t in tags)):
        r.problems.append("repo.tags is not a list of strings")
        tags = []

    current = {s["id"]: version(s) for s in canon.standards}
    standards = data.get("standards", {})
    if not isinstance(standards, dict):
        r.problems.append("[standards] is not a table")
        standards = {}
    for sid, e in sorted(standards.items()):
        if not isinstance(e, dict):
            r.problems.append(f"standards.{sid} is not a table")
            continue
        v, status, latest = _int(e.get("version")), e.get("status"), current.get(sid)
        if v is None:
            r.problems.append(f"standards.{sid}.version is not an integer")
            continue
        if canon.standards and sid not in current:
            r.problems.append(f"standards.{sid} is not in the canon")
            continue
        if latest is not None and v > latest:
            r.problems.append(f"standards.{sid} records v{v}, a version the canon never had (current v{latest})")
            continue
        if status == "adopted":
            r.adopted.append(f"{sid} v{v}")
        elif status == "declined":
            reasons = []
            if not _text(e.get("by")):
                reasons.append("no by")
            if not _text(e.get("reason")):
                reasons.append("no reason")
            if not _is_date(e.get("revisit")):
                reasons.append("revisit is not a date")
            if reasons:
                r.problems.append(f"standards.{sid} is declined with {', '.join(reasons)}")
            r.declined.append(f"{sid} v{v}: {e.get('reason', '')} (revisit {e.get('revisit', '?')})")
        elif status != "pending":
            r.problems.append(f"standards.{sid}.status is {status!r}, not adopted, declined or pending")
            continue
        if latest is not None and latest > v:
            r.newer.append(f"{sid} v{v} → v{latest}")         # a decline answers one version
        elif status == "pending":
            r.newer.append(f"{sid} v{v} (pending)")

    for s in canon.standards:
        if s["id"] not in standards and _applies(s.get("applies_to"), tags):
            r.missing.append(f"{s['id']} v{version(s) or '?'}")

    blocks = data.get("blocks", {})
    if not isinstance(blocks, dict):
        r.problems.append("[blocks] is not a table")
        blocks = {}
    block_versions = {b["id"]: version(b) for b in canon.blocks}
    for bid, e in sorted(blocks.items()):
        v = _int(e.get("version")) if isinstance(e, dict) else None
        if v is None:
            r.problems.append(f"blocks.{bid}.version is not an integer")
            continue
        latest = block_versions.get(bid)
        r.blocks.append(f"{bid} v{v}")
        if latest is not None and latest > v:
            r.newer.append(f"{bid} v{v} → v{latest}")
        elif latest is not None and v > latest:
            r.problems.append(f"blocks.{bid} records v{v}, a version the canon never had (current v{latest})")
    return r

