"""What a repo's .ds/manifest.toml records, against the canon. [[gotcha-validation]]

Never raises on bad input: every malformed value becomes a problem line."""
from __future__ import annotations

import datetime as dt
import fnmatch
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

from .canon import Canon, version


@dataclass
class Report:
    adopted: list[str] = field(default_factory=list)
    declined: list[str] = field(default_factory=list)
    newer: list[str] = field(default_factory=list)
    missing: list[str] = field(default_factory=list)
    blocks: list[str] = field(default_factory=list)
    problems: list[str] = field(default_factory=list)


def _applies(applies_to, tags: list[str]) -> bool:
    if applies_to in (None, "", "*"):
        return True
    patterns = [applies_to] if isinstance(applies_to, str) else applies_to
    if not isinstance(patterns, list):
        return False
    return any(isinstance(p, str) and (p == "*" or any(fnmatch.fnmatchcase(t, p) for t in tags)) for p in patterns)


def _text(v) -> bool:
    return isinstance(v, str) and bool(v.strip())


def _is_date(v) -> bool:
    """A TOML date, or an ISO date string; a datetime is not a date here."""
    if isinstance(v, dt.datetime):
        return False
    if isinstance(v, dt.date):
        return True
    if isinstance(v, str):
        try:
            dt.date.fromisoformat(v)
            return True
        except ValueError:
            return False
    return False


def _int(v) -> int | None:
    return v if isinstance(v, int) and not isinstance(v, bool) else None


def manifest_report(repo: Path, canon: Canon) -> Report:
    r = Report()
    path = Path(repo) / ".ds" / "manifest.toml"
