        r.problems.append("[repo] is missing or not a table")
        repo_t = {}
    tags = repo_t.get("tags", [])
    if not (isinstance(tags, list) and all(isinstance(t, str) for t in tags)):
        r.problems.append("repo.tags is not a list of strings")
        tags = []

    current = {s["id"]: version(s) for s in canon.standards}
    standards = data.get("standards", {})
