            r.declined.append(f"{sid} v{v}: {e.get('reason', '')} (revisit {e.get('revisit', '?')})")
        elif status != "pending":
            r.problems.append(f"standards.{sid}.status is {status!r}, not adopted, declined or pending")
            continue
        if latest is not None and latest > v:
            r.newer.append(f"{sid} v{v} → v{latest}")         # a decline answers one version
        elif status == "pending":
            r.newer.append(f"{sid} v{v} (pending)")

    for s in canon.standards:
        if s["id"] not in standards and _applies(s.get("applies_to"), tags):
            r.missing.append(f"{s['id']} v{version(s) or '?'}")

    blocks = data.get("blocks", {})
    if not isinstance(blocks, dict):
        r.problems.append("[blocks] is not a table")
        blocks = {}
    block_versions = {b["id"]: version(b) for b in canon.blocks}
    for bid, e in sorted(blocks.items()):
        v = _int(e.get("version")) if isinstance(e, dict) else None
        if v is None:
            r.problems.append(f"blocks.{bid}.version is not an integer")
            continue
