from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from cortex_agent_sdk.cortexcode import tool

from .canon import Canon
from .cortex_session import error_result, text_result

SERVER = "kb"
PREFIX = f"mcp__{SERVER}__"
READ_ONLY = {"list_standards", "read_standard", "list_scaffolds", "review_verdict"}


@dataclass
class Review:
    """Verdicts the model reports with review_verdict while a review is open. Approved only when
    at least one verdict came, and every one said ok with no concerns."""
    open: bool = False
    verdicts: list[tuple[bool, list[str]]] = field(default_factory=list)

    def start(self) -> None:
        self.open, self.verdicts = True, []

    def finish(self) -> None:
        self.open = False

    @property
    def approved(self) -> bool:
        return bool(self.verdicts) and all(ok and not concerns for ok, concerns in self.verdicts)

    @property
    def concerns(self) -> list[str]:
        return [c for _, cs in self.verdicts for c in cs]


VERDICT_SCHEMA = {
    "type": "object",
    "properties": {
        "ok": {"type": "boolean", "description": "true only if the draft meets the canon as it stands"},
        "concerns": {"type": "array", "items": {"type": "string"},
                     "description": "each problem found, one per item; empty when ok"},
    },
    "required": ["ok", "concerns"],
}


def make_tools(canon_ref: Any, review: Review) -> list:
    """Tools over `canon_ref()` (a callable returning the current Canon, so /clear can reload it)."""

    @tool("list_standards", "List the canon's standards and gotchas: id, version, kind, title.", {})
    async def list_standards(args: dict) -> dict:
        canon: Canon = canon_ref()
        if canon.error:
            return error_result(canon.error)
        return text_result("\n".join(
            f"{s['id']} v{s.get('version', '?')}{' (gotcha)' if s.get('kind') == 'gotcha' else ''} "
            f"{s.get('title', '')}" for s in canon.standards) or "(no standards)")

    @tool("read_standard", "Read one standard's full text by id.", {"id": str})
    async def read_standard(args: dict) -> dict:
        canon: Canon = canon_ref()
        sid = args.get("id") if isinstance(args, dict) else None
        if not isinstance(sid, str) or not sid:
            return error_result("read_standard needs an id, e.g. 'testing'")
        try:
            return text_result(canon.standard_text(sid))
        except KeyError:
            return error_result(f"no standard {sid!r}; list_standards shows the ids")
        except (OSError, ValueError) as e:
            return error_result(f"cannot read {sid}: {e}")

    @tool("list_scaffolds", "List the canon's project scaffolds: id, version, status, title, tags.", {})
    async def list_scaffolds(args: dict) -> dict:
        canon: Canon = canon_ref()
        if canon.error:
            return error_result(canon.error)
        return text_result("\n".join(
            f"{s['id']} v{s.get('version', '?')} {s.get('status', '?')} {s.get('title', '')} "
            f"tags={','.join(s.get('tags', []) or [])}" for s in canon.scaffolds) or "(no scaffolds)")

    @tool("review_verdict", "Report your review of a project draft. Call it exactly once per review.",
          VERDICT_SCHEMA)
    async def review_verdict(args: dict) -> dict:
        if not review.open:
            return error_result("no review is open; review_verdict is only for reviewing a /new draft")
        ok = args.get("ok") if isinstance(args, dict) else None
        concerns = args.get("concerns") if isinstance(args, dict) else None
        if not isinstance(ok, bool) or not (isinstance(concerns, list) and all(isinstance(c, str) for c in concerns)):
            review.verdicts.append((False, ["the review's verdict was malformed"]))
            return error_result("ok must be a boolean and concerns a list of strings")
        review.verdicts.append((ok, [c.strip() for c in concerns if c.strip()]))
        return text_result("verdict recorded")

    return [list_standards, read_standard, list_scaffolds, review_verdict]

