"""The knowledge base as Cortex tools. All of them only read or report, so none asks for approval.
[[gotcha-agent-trust]] [[gotcha-approvals]]"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from cortex_agent_sdk.cortexcode import tool

from .canon import Canon
from .cortex_session import error_result, text_result

SERVER = "kb"
PREFIX = f"mcp__{SERVER}__"
READ_ONLY = {"list_standards", "read_standard", "list_scaffolds", "review_verdict"}


@dataclass
class Review:
    """Verdicts the model reports with review_verdict while a review is open. Approved only when
    at least one verdict came, and every one said ok with no concerns."""
    open: bool = False
    verdicts: list[tuple[bool, list[str]]] = field(default_factory=list)

    def start(self) -> None:
        self.open, self.verdicts = True, []

    def finish(self) -> None:
        self.open = False

    @property
    def approved(self) -> bool:
        return bool(self.verdicts) and all(ok and not concerns for ok, concerns in self.verdicts)

    @property
    def concerns(self) -> list[str]:
        return [c for _, cs in self.verdicts for c in cs]


VERDICT_SCHEMA = {
    "type": "object",
    "properties": {
        "ok": {"type": "boolean", "description": "true only if the draft meets the canon as it stands"},
        "concerns": {"type": "array", "items": {"type": "string"},
                     "description": "each problem found, one per item; empty when ok"},
    },
    "required": ["ok", "concerns"],
}


def make_tools(canon_ref: Any, review: Review) -> list:
